<template>
  <div class="item-loan">
    <table class="table table-sm table-hover table-stripped mt-1">
      <thead>
        <tr style="font-size: 10pt; font-weight: bold">
          <td colspan="6">VALOR DO EMPRÉSTIMO</td>
          <td colspan="4" class="text-right">
            {{ convertMoney(currentLoan.amount) }}
          </td>
        </tr>
        <tr style="font-size: 10pt; font-weight: bold">
          <td colspan="6">Taxa de juro</td>
          <td colspan="4" class="text-right">
            {{ currentLoan.interestRate * 100 }}%
          </td>
        </tr>
        <tr style="font-size: 10pt; font-weight: bold">
          <td colspan="6">Número de prestações</td>
          <td colspan="4" class="text-right">
            {{ currentLoan.numberOfInstallments }}
          </td>
        </tr>
      </thead>
      <thead>
        <tr style="font-size: 10pt" class="bg-secondary text-white">
          <th>Ordem</th>
          <th class="text-right">Amortização</th>
          <th class="text-right">Juros</th>
          <th class="text-right">Prestação</th>
          <th class="text-right">Juros de mora</th>
          <th class="text-right">Total a pagar</th>
          <th class="text-right">Vencimento</th>
          <th class="text-right">Situação</th>
          <th class="text-center">Acções</th>
        </tr>
      </thead>
      <tbody>
        <tr
          v-for="amortization in customerLoanAmortization"
          :key="amortization.id"
          style="font-size: 9pt; cursor: pointer"
        >
          <td>{{ amortization.installmentOrder }}</td>
          <td
            v-money-format="amortization.amortization"
            class="text-right"
          ></td>
          <td v-money-format="amortization.rateAmount" class="text-right"></td>
          <td v-money-format="amortization.installment" class="text-right"></td>
          <td
            v-money-format="calculateForfeit(amortization)"
            class="text-right"
          ></td>
          <td
            v-money-format="totalWithForfeit(amortization)"
            class="text-right"
          ></td>
          <td v-date-format="amortization.dueDate" class="text-right"></td>
          <td class="text-right">{{ calculateDays(amortization.dueDate) }}</td>
          <td class="text-center">
            <b-row>
              <b-col
                v-if="amortization.status == 0"
                @click="addPayment(amortization)"
                ><b class="text-danger"
                  ><b-icon icon="credit-card" aria-hidden="true"></b-icon>
                  Pagar</b
                ></b-col
              >
              <b-col v-else @click="previewReceipt(amortization)"
                ><b class="text-success"
                  ><b-icon
                    icon="file-earmark-pdf-fill"
                    aria-hidden="true"
                  ></b-icon>
                  PAGO</b
                ></b-col
              >
            </b-row>
          </td>
        </tr>
      </tbody>
    </table>

    <b-modal
      hide-footer
      size="md"
      scrollable
      ref="place-payment"
      title="Adicionar pagamento"
    >
      <div>
        <b-overlay :show="isLoading" rounded="sm">
          <b-row v-if="1 > 5"
            ><b-col
              ><small>Data de pagamento</small>
              <b-form-datepicker
                v-model="loanPayment.paymentDate"
                :disabled="paymentMethod == 7"
                size="sm"
                class="mt-2 mb-2"
              ></b-form-datepicker> </b-col
          ></b-row>
          <b-row>
            <b-col
              ><small>Meio de pagamento</small>
              <b-form-select
                class="mt-2"
                v-model="paymentMethod"
                :options="options"
                size="sm"
              ></b-form-select
            ></b-col>
            <b-col
              ><small>Referência de pagamento</small>
              <b-form-group label-for="payment_reference" class="mt-1">
                <b-form-input
                  type="text"
                  :disabled="paymentMethod == 7 || paymentMethod == 1"
                  size="sm"
                  v-model="loanPayment.paymentReference"
                ></b-form-input> </b-form-group
            ></b-col>
          </b-row>
          <b-row>
            <b-col
              ><small>Valor a pagar</small>
              <b-form-group label-for="amount_received" class="mt-1">
                <b-form-input
                  type="number"
                  disabled
                  size="sm"
                  step="any"
                  :min="0"
                  v-model="loanPayment.amountReceived"
                ></b-form-input> </b-form-group
            ></b-col>
            <b-col
              ><small>Saldo devedor</small>
              <b-form-group label-for="debit_balance" class="mt-1">
                <b-form-input
                  type="number"
                  size="sm"
                  step="any"
                  v-model="loanPayment.debitBalance"
                  disabled
                ></b-form-input> </b-form-group
            ></b-col>
          </b-row>
          <b-row v-if="paymentMethod == 7">
            <b-col
              ><small>Número Vodacom válido</small>
              <b-form-group label-for="vodacomNumber" class="mt-2">
                <b-form-input
                  type="number"
                  size="sm"
                  v-model="loanPayment.phoneNumber"
                ></b-form-input> </b-form-group></b-col
          ></b-row>
          <b-row>
            <b-col
              ><b-button
                @click="finalizepayment()"
                v-if="paymentMethod != 7"
                :disabled="isLoading"
                block
                size="sm"
                variant="secondary"
                >Submeter</b-button
              >
              <b-button
                @click="payViaMpesa()"
                v-else
                :disabled="isLoading"
                block
                size="sm"
                variant="secondary"
                >Pagar via M-Pesa</b-button
              >
            </b-col>
          </b-row>
        </b-overlay>
      </div>
    </b-modal>
  </div>
</template>
<script>
import { mapGetters } from "vuex";
import axios from "axios";
import MoneyFormat from "@/utils/moneyFormat";
import logs from "@/utils/logs";

// PDF Generator
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;
import moment from "moment";

export default {
  name: "item-loan",

  data: () => ({
    customerLoanAmortization: [],
    loanPayment: {
      paymentReference: "",
      debitBalance: 0,
      amountReceived: 0,
      paymentDate: "",
      phoneNumber: "",
      amortizationLoanId: 0,
      currentAmortization: {},
      installmentOrder: 0,
    },

    paymentMethod: 1,

    options: [
      { value: 1, text: "Boca do Caixa" },
      { value: 2, text: "Depósito Bancário" },
      { value: 3, text: "Transferência Bancária" },
      { value: 4, text: "POS" },
      { value: 5, text: "Cheque" },
      { value: 6, text: "M-Pesa USSD" },
      { value: 7, text: "M-Pesa Open API" },
      { value: 8, text: "E-Mola" },
    ],
    today: moment(),
  }),

  props: ["currentLoan"],

  created() {
    this.getAmortizationLoans();
  },

  watch: {
    paymentMethod: function () {
      if (this.paymentMethod != 1) {
        this.loanPayment.paymentReference = "";
      }
    },
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "currentCustomer",
      "customerTranzactions",
      "company",
    ]),
  },

  methods: {
    getAmortizationLoans() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/loan/amortization/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.customerLoanAmortization = data.result;
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.customerLoanAmortization = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.customerLoanAmortization = [];
        });
    },

    calculateDays(dueDate) {
      const diffDays = this.today.diff(dueDate, "days");
      return diffDays >= 0 ? diffDays + " dias atrazado" : "Dentro do prazo";
    },

    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    calculateForfeit(amortization) {
      const diffDays = this.today.diff(amortization.dueDate, "days");
      const forfeitValue =
        amortization.installment * (this.company.forfeit / 100);
      return diffDays >= 0 ? forfeitValue * diffDays : 0;
    },

    totalWithForfeit(amortization) {
      const diffDays = this.today.diff(amortization.dueDate, "days");
      const forfeitValue =
        amortization.installment * (this.company.forfeit / 100);
      return diffDays >= 0
        ? forfeitValue * diffDays + amortization.installment
        : amortization.installment;
    },

    async previewReceipt(amortization) {
      console.log(amortization);
      const tranzactions = this.customerTranzactions.filter((a) => {
        return a.amortizationLoanId === amortization.id;
      });

      const body = [];

      for (let row of tranzactions) {
        const rows = [];

        rows.push({ text: row.id, fontSize: 9 });
        rows.push({ text: row.tranzactionReference, fontSize: 9 });
        rows.push({
          text: MoneyFormat.formatMoney(row.amount),
          fontSize: 9,
          alignment: "right",
        });
        body.push(rows);
      }

      let docDefinition = {
        // watermark: { text: this.company[0].name, opacity: 0.08 },
        // header: [
        //   {
        //     image: await this.getBase64ImageFromURL(this.company.companyLogo),
        //     width: 300,
        //     height: 200,
        //     margin: [30, 0, 0, 0],
        //   },
        // ],
        footer: {
          columns: [
            {
              text: "Documento processado por computador",
              alignment: "left",
              fontSize: 8,
              margin: [30, 0, 0, 0],
            },
            {
              text: this.company.companyName,
              alignment: "right",
              fontSize: 8,
              margin: [0, 0, 30, 0],
            },
          ],
        },

        content: [
          {
            columns: [
              // COMPANY DETAILS
              [
                {
                  text: this.company.companyName,
                  fontSize: 12,
                  bold: true,
                  alignment: "left",
                },
                {
                  text: `${this.company.companyAddress}`,
                  fontSize: 10,
                  alignment: "left",
                },
                {
                  text: `NUIT: ${this.company.companyNuit}`,
                  fontSize: 10,
                  alignment: "left",
                },
                {
                  text: `E-mail: ${this.company.companyEmail}`,
                  fontSize: 10,
                  alignment: "left",
                },
                {
                  text: `Telefone: ${this.company.companyPhone}`,
                  fontSize: 10,
                  alignment: "left",
                },
                {
                  text: `Website: ${this.company.companyWebsite}`,
                  fontSize: 10,
                  alignment: "left",
                },
              ],
              // CUSTOMER DETAILS
              [
                {
                  text: `Nome: ${this.currentCustomer.customerName}`,
                  bold: true,
                  fontSize: 12,
                },
                {
                  text: `${this.currentCustomer.customerAddress}`,
                  style: "customerStyle",
                },
                {
                  text: `Telefone: ${this.currentCustomer.customerPhone}`,
                  style: "customerStyle",
                },
                {
                  text: `NUIT: ${this.currentCustomer.customerNuit}`,
                  style: "customerStyle",
                },
                {
                  text: `E-mail: ${this.currentCustomer.customerEmail}`,
                  style: "customerStyle",
                },
              ],
            ],
          },
          {
            text: "\n\n",
          },
          {
            table: {
              widths: ["auto", "auto", "*"],
              body: [
                [
                  { text: "Nr recibo", style: "columnsTitle" },
                  {
                    text: "Referência",
                    style: "columnsTitle",
                    alignment: "center",
                  },
                  {
                    text: "Montante",
                    style: "columnsTitle",
                    alignment: "right",
                  },
                ],
                ...body,
              ],
            },
            layout: "lightHorizontalLines",
          },
          {
            text: "\n",
          },
        ],
        styles: {
          paymentMethodStyle: {
            bold: true,
            fontSize: 10,
          },
          sectionHeader: {
            bold: true,
            fontSize: 10,
            margin: [0, 15, 0, 15],
          },
          columnsTitle: {
            fontSize: 10,
            bold: true,
            color: "#000000",
          },
          columnsSubTotals: {
            fontSize: 10,
            bold: true,
            color: "#000000",
          },
          columnsTotal: {
            fontSize: 12,
            bold: true,
            color: "#000000",
          },
          companyDetailsStyle: {
            fontSize: 9,
            bold: true,
            color: "#000000",
          },
          customerStyle: {
            fontSize: 10,
            bold: false,
          },
        },
      };

      // pdfMake.createPdf(docDefinition).download(`proforma${this.currentQuotation.name}.pdf`);
      pdfMake.createPdf(docDefinition).open();
    },

    addPayment(amortization) {
      this.currentAmortization = amortization;
    //   console.log(this.currentAmortization);
      this.$refs["place-payment"].show();
      this.loanPayment.debitBalance = 0;
      this.loanPayment.paymentReference = `${this.currentCustomer.accountNumber}PY${amortization.id}`;
      this.paymentMethod = 1;
      this.loanPayment.phoneNumber = this.currentCustomer.customerPhone;
      this.loanPayment.amortizationLoanId = amortization.id;
      this.loanPayment.installmentOrder = amortization.installmentOrder;
      this.loanPayment.amountReceived = this.totalWithForfeit(amortization);
      // console.log(parseFloat(amortization.installment));
    },

    payViaMpesa() {
      if (this.loanPayment.phoneNumber.length != 12) {
        this.showToast("Avizo!", "warning", "O número que digitou é inválido.");
        return;
      } else {
        const passingValues = {
          from: this.loanPayment.phoneNumber + "",
          reference: this.currentCustomer.accountNumber + "",
          amount: this.loanPayment.amountReceived + "",
          transaction:
            this.currentCustomer.accountNumber +
            "PY" +
            this.loanPayment.amortizationLoanId,
        };

        this.$store.commit("LOADING_STATUS", true);
        axios
          .put(`/api/mpesa/receive`, passingValues)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              const response = data.result;
              if (
                response.output_ResponseDesc == "Request processed successfully"
              ) {
                this.showToast(
                  "Sucesso!",
                  "success",
                  "Pagamento efectuado com sucesso."
                );
                this.addTransaction(response);
              }
            } else {
              this.showToast("Erro!", "danger", data.message);
              const response = data.result;
              if (response.output_ResponseDesc == "Duplicate Transaction") {
                this.showToast(
                  "Erro!",
                  "danger",
                  "Tranzação duplicada, tente mais tarde"
                );
              }
            }
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
            console.log(err);
          });
      }
    },

    addTransaction(mpesa) {
      const passingValues = {
        tranzactionReference: mpesa.output_TransactionID.toUpperCase(),
        accountNumber: this.currentCustomer.accountNumber,
        phoneNumber: this.loanPayment.phoneNumber,
        staffName: this.user.name,
        companyId: this.company.id,
        amount: this.loanPayment.amountReceived,
        latePaymentInterest: this.calculateForfeit(this.currentAmortization),
        interestRateAmount: this.currentAmortization.rateAmount,
        paymentMethod: this.paymentMethod,
        amortizationLoanId: this.loanPayment.amortizationLoanId,
        description: `Confirmado!. Recebemos ${MoneyFormat.formatMoney(
          this.loanPayment.amountReceived
        )} referente ao pagamento da ${
          this.loanPayment.installmentOrder
        } com a referência ${mpesa.output_TransactionID.toUpperCase()} da dívida.`,
      };

      this.$store.commit("LOADING_STATUS", true);
      axios
        .post(`/api/tranzaction`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast(
              "Sucesso!",
              "success",
              "Pagamento efectuado com sucesso"
            );
            const logsParams = logs(
              this.user,
              `${passingValues.description}`,
              "Desembolso de crédito"
            );
            this.$store.dispatch("addLog", logsParams);
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.getAmortizationLoans();
          this.$refs["place-payment"].hide();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["place-payment"].hide();
        });
    },

    finalizepayment() {
      const passingValues = {
        tranzactionReference: this.loanPayment.paymentReference,
        accountNumber: this.currentCustomer.accountNumber,
        phoneNumber: "Não disponível",
        staffName: this.user.name,
        companyId: this.company.id,
        amount: this.loanPayment.amountReceived,
        latePaymentInterest: this.calculateForfeit(this.currentAmortization),
        interestRateAmount: this.currentAmortization.rateAmount,
        paymentMethod: this.paymentMethod,
        amortizationLoanId: this.loanPayment.amortizationLoanId,
        description: `Confirmado!. Recebemos ${MoneyFormat.formatMoney(
          this.loanPayment.amountReceived
        )} referente ao pagamento da ${
          this.loanPayment.installmentOrder
        } com a referência ${this.loanPayment.paymentReference} da dívida.`,
      };

      if (passingValues.tranzactionReference.length < 10) {
        this.showToast(
          "Avizo!",
          "warning",
          "Digite a referência do pagamento por favor."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        axios
          .post(`/api/tranzaction`, passingValues)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast(
                "Sucesso!",
                "success",
                "Pagamento efectuado com sucesso"
              );
              const logsParams = logs(
                this.user,
                `${passingValues.description}`,
                "Desembolso de crédito"
              );
              this.$store.dispatch("addLog", logsParams);
            } else {
              this.showToast("Erro!", "danger", data.message);
            }
            this.getAmortizationLoans();
            this.$refs["place-payment"].hide();
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
            this.$refs["place-payment"].hide();
          });
      }
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    getBase64ImageFromURL(url) {
      return new Promise((resolve, reject) => {
        var img = new Image();
        img.setAttribute("crossOrigin", "anonymous");

        img.onload = () => {
          var canvas = document.createElement("canvas");
          canvas.width = img.width;
          canvas.height = img.height;

          var ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0);

          var dataURL = canvas.toDataURL("image/png");

          resolve(dataURL);
        };

        img.onerror = (error) => {
          reject(error);
        };

        img.src = url;
      });
    },
  },
};
</script>
