<template>
  <div class="borrower-view">
    <NavBarVue />
    <b-container fluid class="bv-example-row">
      <div class="container-group">
        <div class="card">
          <div class="card-body">
            <b-row>
              <b-col lg="3" md="5" sm="12">
                <h5 class="text-secondary">
                  <b-icon icon="credit-card-fill" variant="secondary"></b-icon
                  >&nbsp;&nbsp;&nbsp;<b>{{ currentCustomer.accountNumber }}</b>
                </h5>

                <h6 class="text-secondary mt-1">
                  <b-icon icon="file-earmark-plus"></b-icon>
                  <small> <b> Adicionar Documentos</b></small>
                </h6>
                <b-input-group size="sm" class="mt-1">
                  <b-input-group-prepend is-text>
                    <b-icon icon="file-earmark-pdf"></b-icon>
                  </b-input-group-prepend>
                  <b-form-input
                    type="text"
                    size="sm"
                    v-model="form.documentName"
                    placeholder="Descrição do documento"
                  ></b-form-input>
                </b-input-group>

                <b-form-file
                  accept="*"
                  @change="onFileChange"
                  class="mt-2 mb-2"
                  size="sm"
                ></b-form-file>
                <b-progress
                  :value="uploadValue"
                  :max="100"
                  show-progress
                  animated
                  class="mt-1 mb-1"
                  v-if="uploadValue > 0"
                ></b-progress>
                <b-button
                  :disabled="
                    isLoading ||
                    uploadValue > 0 ||
                    !selectedFile ||
                    !form.documentName
                  "
                  type="submit"
                  size="sm"
                  variant="secondary"
                  @click="onUploadFile()"
                  class="mt-2 mb-2"
                  block
                  >Salvar documento
                  <b-icon icon="cloud-upload-fill" font-scale="1"></b-icon
                ></b-button>

                <b-row
                  class="text-secondary mt-1"
                  v-if="customerDocuments.length > 0"
                >
                  <b-col lg="12">
                    <h6>
                      <b-icon icon="list-check"></b-icon>
                      <small><b> Documentos submetidos</b></small>
                    </h6>
                    <b-list-group>
                      <b-list-group-item
                        class="d-flex justify-content-between align-items-center"
                        v-for="(doc, index) in customerDocuments"
                        :key="doc.id"
                      >
                        <small>
                          <b>{{ index + 1 }}.</b> {{ doc.documentName }}</small
                        >
                        <b-row>
                          <b-col @click="deleteDocument(doc)">
                            <b-badge
                              variant="danger"
                              pill
                              style="cursor: pointer"
                              ><b-icon
                                icon="trash-fill"
                                aria-hidden="true"
                              ></b-icon
                            ></b-badge>
                          </b-col>
                          <b-col>
                            <a :href="doc.documentFileUrl" target="_blank">
                              <b-badge
                                variant="secondary"
                                pill
                                style="cursor: pointer"
                                ><b-icon
                                  icon="cloud-download"
                                  aria-hidden="true"
                                ></b-icon
                              ></b-badge>
                            </a>
                          </b-col>
                        </b-row> </b-list-group-item
                    ></b-list-group>
                  </b-col>
                </b-row>
              </b-col>

              <b-col>
                <b-row class="mb-1">
                  <b-col lg="9"
                    ><h4 class="text-secondary">
                      <b>{{ currentCustomer.customerName }}</b>
                    </h4></b-col
                  >
                  <b-col>
                    <b-button
                      type="submit"
                      size="sm"
                      block
                      variant="secondary"
                      @click="previewSimulator()"
                      >Simular &nbsp;<b-icon icon="aspect-ratio"></b-icon
                    ></b-button>
                  </b-col>
                </b-row>
                <b-row>
                  <b-col>
                    <b-input-group size="sm" class="">
                      <b-input-group-prepend is-text>
                        <b>Salário mensal</b>
                      </b-input-group-prepend>
                      <b-form-input
                        type="text"
                        size="sm"
                        disabled
                        v-model="currentCustomerSalary"
                        :placeholder="currentCustomerSalary"
                      ></b-form-input>
                    </b-input-group>
                  </b-col>
                  <b-col>
                    <b-input-group size="sm" class="">
                      <b-input-group-prepend is-text>
                        Crédito (<b>MZN</b>)
                      </b-input-group-prepend>
                      <b-form-input
                        type="number"
                        min="100"
                        step="any"
                        size="sm"
                        v-model="loan.capital"
                        placeholder="Crédito"
                      ></b-form-input>
                    </b-input-group>
                  </b-col>
                  <b-col cols="2">
                    <b-form-group label-for="input-5">
                      <b-form-select
                        v-model="loan.prestacoes"
                        size="sm"
                        :options="numeroPrestacoes"
                        required
                      ></b-form-select>
                    </b-form-group>
                  </b-col>
                  <b-col>
                    <b-form-group label-for="input-5">
                      <b-form-select
                        v-model="loan.juros"
                        size="sm"
                        :options="typeOfCredit"
                        required
                      ></b-form-select>
                    </b-form-group>
                  </b-col>
                </b-row>
                <b-overlay :show="isLoading" rounded="sm">
                  <table
                    v-if="customerLoanAmortization.length > 0"
                    class="table table-sm table-hover table-stripped mt-1"
                  >
                    <thead>
                      <tr style="font-size: 10pt; font-weight: bold">
                        <td colspan="4">CAPITAL A FINANCIAR</td>
                        <td colspan="2" class="text-right">
                          {{ convertMoney(loan.capital) }}
                        </td>
                      </tr>
                      <tr style="font-size: 10pt; font-weight: bold">
                        <td colspan="4">Taxa de juros</td>
                        <td colspan="2" class="text-right">
                          {{ loan.juros * 100 }}%
                        </td>
                      </tr>
                      <tr style="font-size: 10pt; font-weight: bold">
                        <td colspan="4">Número de prestações</td>
                        <td colspan="2" class="text-right">
                          {{ loan.prestacoes }}
                        </td>
                      </tr>
                      <tr style="font-size: 10pt; font-weight: bold">
                        <td colspan="4">TOTAL A PAGAR</td>
                        <td
                          colspan="2"
                          class="text-right"
                          v-money-format="total2Pay"
                        ></td>
                      </tr>
                    </thead>
                    <thead>
                      <tr
                        style="font-size: 10pt"
                        class="bg-secondary text-white"
                      >
                        <th>Ordem</th>
                        <th class="text-right">Amortização</th>
                        <th class="text-right">Juros</th>
                        <th class="text-right">Prestação</th>
                        <th class="text-right">Vencimento</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr
                        v-for="amortization in customerLoanAmortization"
                        :key="amortization.id"
                        style="font-size: 9pt; cursor: pointer"
                      >
                        <td>{{ amortization.installmentOrder }}</td>
                        <td
                          v-money-format="amortization.capitalPerInstall"
                          class="text-right"
                        ></td>
                        <td
                          v-money-format="amortization.rateAmount"
                          class="text-right"
                        ></td>
                        <td
                          v-money-format="amortization.installment"
                          class="text-right"
                        ></td>
                        <td
                          v-date-format="amortization.dueDate"
                          class="text-right"
                        ></td>
                      </tr>
                    </tbody>
                  </table>
                  <b-row v-if="customerLoanAmortization.length > 0">
                    <b-col lg="6">
                      <b-form-group
                        label="Observações do técnico"
                        label-for="textarea-formatter"
                        class="mb-0"
                        style="font-weight: bold; font-size: 10pt"
                      >
                        <b-form-textarea
                          id="textarea-formatter"
                          v-model="loan.loanDescription"
                          placeholder="Parecer Técnico"
                        ></b-form-textarea>
                      </b-form-group>
                    </b-col>
                    <b-col>
                      <p><br /></p>
                      <b-form-group label-for="input-5">
                        <b-form-select
                          v-model="loan.creditManager"
                          size="sm"
                          :options="creditManangers"
                          required
                        ></b-form-select>
                      </b-form-group>
                    </b-col>
                    <b-col cols="1">
                      <p><br /></p>
                      <b-button
                        :disabled="isLoading"
                        type="submit"
                        size="sm"
                        block
                        @click="closeSimulater()"
                        ><b-icon icon="x-lg" variant="danger"></b-icon
                      ></b-button>
                    </b-col>
                    <b-col cols="2">
                      <p><br /></p>
                      <b-button
                        :disabled="isLoading"
                        type="submit"
                        size="sm"
                        block
                        variant="success"
                        @click="createLoan()"
                        >Submeter &nbsp;<b-icon icon="telegram"></b-icon
                      ></b-button>
                    </b-col>
                  </b-row>

                  <b-row class="mb-1" v-if="customerLoans.length > 0">
                    <b-col>
                      <LoansItems />
                    </b-col>
                  </b-row>
                </b-overlay>
              </b-col>
            </b-row>
          </div>
        </div>
      </div>
    </b-container>

    <b-modal hide-footer ref="delete-document" title="Deletar">
      <p class="text-danger text-center">
        Deseja realmente eliminar este documento?
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block size="sm" variant="danger" @click="decidedToDelete()"
            >Deletar</b-button
          >
        </b-col>
      </b-row>
    </b-modal>
  </div>
</template>

<script>
import axios from "axios";
import firebase from "firebase";
import { mapGetters } from "vuex";
import NavBarVue from "@/components/NavBar";
import LoansItems from "@/components/loans/LoansItems";
import MoneyFormat from "../utils/moneyFormat";
import logs from "@/utils/logs";
import loanSimulator from "@/utils/loanAmortization";
import moment from "moment";

export default {
  name: "BorrowerView",

  components: {
    NavBarVue,
    LoansItems,
  },

  data: () => ({
    form: {
      accountNumber: "",
      documentFileUrl: "",
      documentName: "",
      uploadedBy: "",
    },

    today: moment(),

    loan: {
      capital: 0,
      juros: null,
      prestacoes: null,
      creditManager: null,
      loanDescription: "",
    },

    typeOfCredit: [{ text: "Taxa de juros", value: null }],
    numeroPrestacoes: [
      { text: "Prestação", value: null },
      { text: "Diária", value: 30 },
      { text: "Semanal", value: 4 },
      { text: "Quizenal", value: 2 },
      { text: "Mensal", value: 1 },
    ],
    creditManangers: [{ text: "Seleccionar Gestor De Crédito", value: null }],
    customerLoanAmortization: [],
    total2Pay: 0,

    selectedFile: "",
    uploadValue: 0,
    documentDeletionId: 0,
    customerDocuments: [],
    tranzactions: [],
    currentCustomerSalary: 0,
    maximumCapacity: 0,
    elegibility: false,
  }),

  created() {
    this.$store.dispatch("getAllUsers", this.company.id);
    // this.creditManangers = this.users;
    this.form.uploadedBy = this.user.name;
    this.form.accountNumber = this.currentCustomer.accountNumber;
    this.getDocuments();

    this.interestRates.forEach((rate) => {
      let item = { text: `${rate.tax * 100}% - ${rate.name}`, value: rate.tax };
      this.typeOfCredit.push(item);
    });

    this.users.forEach((user) => {
      let item = { text: user.name, value: user.id };
      this.creditManangers.push(item);
    });

    this.currentCustomerSalary = MoneyFormat.formatMoney(
      this.currentCustomer.customerMonthlySalary
    );
    this.getCustomerLoans();
    this.getCustomerTranzactions();
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "users",
      "token",
      "currentCustomer",
      "customerLoans",
      "interestRates",
      "company",
    ]),
  },

  methods: {
    getDocuments() {
      this.selectedFile = "";
      this.uploadValue = 0;
      this.form.documentFileUrl = "";
      this.form.documentName = "";

      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/document/${this.currentCustomer.accountNumber}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.customerDocuments = data.result;
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.customerDocuments = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.customerDocuments = [];
        });
    },

    closeSimulater() {
      this.customerLoanAmortization = [];
    },

    getCustomerTranzactions() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/tranzaction/${this.currentCustomer.accountNumber}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.$store.commit("SET_CUSTOMER_TRANZACTIONS", data.result);
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.$store.commit("SET_CUSTOMER_TRANZACTIONS", []);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$store.commit("SET_CUSTOMER_TRANZACTIONS", []);
        });
    },

    getCustomerLoans() {
      this.$store.dispatch(
        "getCustomerLoans",
        this.currentCustomer.accountNumber
      );
    },

    createLoan() {
      if (this.loan.loanDescription.length < 10) {
        this.showToast(
          "Avizo!",
          "warning",
          "O parecer técnico é de preenchimento obrigatório."
        );
        return;
      }

      if (this.loan.creditManager == null) {
        this.showToast("Avizo!", "warning", "Seleccione o Gestor De Crédito");
        return;
      }

      this.$store.commit("LOADING_STATUS", true);
      const passingValues = {
        accountNumber: this.currentCustomer.accountNumber,
        companyId: this.company.id,
        amount: this.loan.capital,
        numberOfInstallments: this.loan.prestacoes,
        interestRate: this.loan.juros,
        creditManager: this.loan.creditManager,
        loanDescription: this.loan.loanDescription,
        status: 0,
      };

      axios
        .post(`/api/loan`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            const logsParams = logs(
              this.user,
              `A conta ${
                passingValues.accountNumber
              } recebeu um financiamento de ${this.convertMoney(
                passingValues.amount
              )} a uma taxa de juros de ${
                passingValues.interestRate * 100
              }%. Nº de prestações: ${passingValues.numberOfInstallments}.`,
              "Novo financiamento"
            );
            this.$store.dispatch("addLog", logsParams);
            this.customerLoanAmortization = [];
            this.getCustomerLoans();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.customerLoans = [];
        });
    },

    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    previewSimulator() {
      if (this.loan.capital < 100) {
        this.showToast(
          "Avizo!",
          "warning",
          "O crédito deve ser maior que 100.00 MZN"
        );
      } else if (this.loan.juros == null) {
        this.showToast(
          "Avizo!",
          "warning",
          "Seleccione a taxa de juros por favor"
        );
      } else if (this.loan.prestacoes == null) {
        this.showToast("Avizo!", "warning", "Seleccione a prestação por favor");
      } else {
        this.customerLoanAmortization = loanSimulator(this.loan);
        // console.log(this.customerLoanAmortization);

        const installment = this.customerLoanAmortization[0].installment;

        const taxaReforco =
          parseFloat(this.currentCustomer.customerMonthlySalary) * 0.3;
        this.elegibility = installment <= taxaReforco ? true : false;

        this.maximumCapacity = taxaReforco;

        this.total2Pay = this.customerLoanAmortization.reduce(
          (sum, p) => sum + p.installment,
          0
        );
      }
    },

    cancelDeletion() {
      this.$refs["delete-document"].hide();
    },

    deleteDocument(document) {
      this.documentDeletionId = document.id;
      this.$refs["delete-document"].show();
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/document/${this.documentDeletionId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            this.getDocuments();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-document"].hide();
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    onFileChange(e) {
      this.selectedFile = e.target.files[0];
    },

    onUploadFile() {
      if (!this.selectedFile) {
        this.showToast(
          "Erro!",
          "warning",
          "Seleccione um documento por favor!"
        );
        return;
      }

      if (!this.form.documentName) {
        this.showToast(
          "Erro!",
          "warning",
          "Digite a descrição do documento por favor!"
        );
        return;
      }
      this.$store.commit("LOADING_STATUS", true);
      const storageRef = firebase
        .storage()
        .ref(
          `/customer/${this.currentCustomer.accountNumber}/${this.selectedFile.name}`
        )
        .put(this.selectedFile);
      storageRef.on(
        `state_changed`,
        (snapshot) => {
          this.uploadValue =
            (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        },
        (err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", true);
        },
        () => {
          this.uploadValue = 0;
          storageRef.snapshot.ref.getDownloadURL().then((url) => {
            this.form.documentFileUrl = url;
            this.uploadCustomerDocument();
          });
        }
      );
    },

    uploadCustomerDocument() {
      this.$store.commit("LOADING_STATUS", true);
      this.form.companyId = this.company.id;
      axios
        .post(`/api/document`, this.form)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${this.form.documentFileUrl} carregado com sucesso.`,
              "Cadastro de documentos"
            );
            this.$store.dispatch("addLog", logsParams);

            this.getDocuments();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    uploadFile2Database() {
      if (!this.selectedFile) {
        this.showToast(
          "Erro!",
          "warning",
          "Seleccione um documento por favor!"
        );
        return;
      }

      if (!this.form.documentName) {
        this.showToast(
          "Erro!",
          "warning",
          "DIgite a descrição do documento por favor!"
        );
        return;
      }
      let formData = new FormData();
      formData.append("file", this.selectedFile);

      this.$store.commit("LOADING_STATUS", true);
      axios
        .post(`/api/upload`, formData)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            // this.showToast("Sucesso!", "success", data.message);
            this.form.documentFileUrl = data.imageUrl;
            this.uploadCustomerDocument();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    calculatePendingDays(dueDate) {
      const diffDays = this.today.diff(dueDate, "days");
      return diffDays;
    },
  },
};
</script>
<style lang="scss" scoped>
.container-group {
  overflow: hidden auto;
  margin-left: -15px;
  width: calc(100% + 30px);
  height: calc(100vh - 55px);
  .container {
    font-size: 10pt;
    padding-top: 0px;
    padding-bottom: 15px;
  }
}

.table {
  font-size: 10px;
  text-align: left;

  tr {
    cursor: pointer;
  }
}
</style>
