<template>
  <div class="item-loan">
    <table
      v-if="customerLoans.length > 0"
      class="table table-sm table-hover table-stripped mt-1"
    >
      <thead>
        <tr style="font-size: 10pt" class="bg-secondary text-white">
          <th>Ordem</th>
          <td>Data De Submissão</td>
          <td>Nº Prestações</td>
          <td>Taxa De Juros</td>
          <td>Montante Financiado</td>
          <td>Estado Do Crédito</td>
          <td class="text-center">Acções</td>
        </tr>
      </thead>
      <tbody>
        <tr
          style="font-size: 9pt"
          v-for="(loan, index) in customerLoans"
          :key="index"
        >
          <td>{{ index + 1 }}</td>
          <td v-date-format="loan.createdAt"></td>
          <td>{{ loan.numberOfInstallments }}</td>
          <td>{{ loan.interestRate * 100 }}%</td>
          <td v-money-format="loan.amount"></td>
          <td>{{ getLoanStatus(loan.status) }}</td>
          <td v-if="loan.status > -1">
            <b-row class="text-center">
              <b-col>
                <b-badge
                  v-if="loan.status > 0"
                  @click="getLoanAmortization(loan)"
                  variant="primary"
                  pill
                  style="cursor: pointer; font-size: 10pt"
                  ><b-icon icon="eye-fill" aria-hidden="true"></b-icon>
                  Pagamentos</b-badge
                >
                <b-badge
                  v-else
                  @click="deleteLoan(loan)"
                  variant="danger"
                  pill
                  style="cursor: pointer; font-size: 10pt"
                  ><b-icon icon="trash-fill" aria-hidden="true"></b-icon>
                  Deletar</b-badge
                >
              </b-col>
              <b-col
                ><b-badge
                  @click="previewLoan(loan)"
                  variant="success"
                  pill
                  style="cursor: pointer; font-size: 10pt"
                  ><b-icon icon="image-fill" aria-hidden="true"></b-icon>
                  Garantias
                </b-badge>
              </b-col>
              <b-col
                ><b-badge
                  variant="success"
                  pill
                  style="cursor: pointer; font-size: 10pt"
                  @click="printContract(loan)"
                >
                  <b-icon icon="eye-fill" aria-hidden="true"></b-icon>
                  Visualizar
                </b-badge>
              </b-col>
            </b-row>
          </td>
          <td v-else class="text-right">
            <b-badge
              variant="danger"
              pill
              style="cursor: pointer; font-size: 10pt"
              ><b-icon icon="xl" aria-hidden="true"></b-icon> Financiamento
              rejeitado</b-badge
            >
          </td>
        </tr>
      </tbody>
    </table>

    <b-modal
      hide-footer
      ref="preview-loan"
      title="Bens Apresentados Como Garantia"
      size="lg"
    >
      <b-overlay :show="isLoading" rounded="sm">
        <div v-if="currentLoan.status == 0">
          <b-row>
            <b-col></b-col>
            <b-col lg="8">
              <b-form-group
                label-for="textarea-formatter"
                class="mb-0 text-center"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-textarea
                  class="text-center"
                  id="textarea-formatter"
                  v-model="form.guaranteeDescription"
                  placeholder="Descrição da garantia"
                ></b-form-textarea>
              </b-form-group>
            </b-col>
            <b-col></b-col>
          </b-row>
          <b-row>
            <b-col>
              <b-input-group size="sm" class="mt-1">
                <b-input-group-prepend is-text>
                  <b>Preço estimado - MZN</b>
                </b-input-group-prepend>
                <b-form-input
                  type="number"
                  step="any"
                  min="100"
                  size="sm"
                  v-model="form.purchaseAmount"
                  placeholder="Montante"
                ></b-form-input> </b-input-group
            ></b-col>
            <b-col
              ><b-form-file
                accept="*"
                @change="onFileChange"
                class="mt-2 mb-2"
                size="sm"
              ></b-form-file
            ></b-col>
            <b-col cols="2">
              <b-button
                :disabled="
                  isLoading ||
                  uploadValue > 0 ||
                  !selectedFile ||
                  !form.guaranteeDescription
                "
                type="submit"
                size="sm"
                variant="success"
                @click="onUploadFile()"
                class="mt-2 mb-2"
                block
                >Gravar <b-icon icon="cloud-upload-fill" font-scale="1"></b-icon
              ></b-button>
            </b-col>
          </b-row>
          <b-row>
            <b-col class="text-center" cols="12">
              <b-progress
                :value="uploadValue"
                :max="100"
                show-progress
                animated
                class="mt-1 mb-1"
                v-if="uploadValue > 0"
              ></b-progress>
            </b-col>
          </b-row>
        </div>
        <table
          v-if="loanGuarantees.length > 0"
          class="table table-sm table-hover table-stripped mt-1"
        >
          <thead>
            <tr style="font-size: 10pt; font-weight: bold">
              <th>#</th>
              <td colspan="2">Descrição da Garantia</td>
              <td class="text-right">Valor estimado</td>
              <td class="text-center">Acções</td>
            </tr>
          </thead>
          <tbody>
            <tr
              v-for="(guarantee, index) in loanGuarantees"
              :key="guarantee.id"
              style="font-size: 9pt"
            >
              <th>{{ index + 1 }}</th>
              <td colspan="2">{{ guarantee.guaranteeDescription }}</td>
              <td
                class="text-right"
                v-money-format="guarantee.purchaseAmount"
              ></td>
              <td>
                <b-row>
                  <b-col
                    class="text-right"
                    @click="deleteGuarantee(guarantee.id)"
                    ><b-badge
                      variant="danger"
                      pill
                      style="cursor: pointer; font-size: 10pt"
                      ><b-icon icon="trash-fill" aria-hidden="true"></b-icon>
                      Deletar</b-badge
                    ></b-col
                  >
                  <b-col class="text-right"
                    ><b-badge
                      variant="secondary"
                      pill
                      style="cursor: pointer; font-size: 10pt"
                      ><b-icon icon="pen" aria-hidden="true"></b-icon>
                      Editar</b-badge
                    ></b-col
                  >
                </b-row>
              </td>
            </tr>
            <tr style="cursor: pointer; font-size: 10pt">
              <th colspan="4">Valor total das garantias</th>
              <th class="text-right" v-money-format="totalGuaranteeAmount"></th>
            </tr>
            <tr style="cursor: pointer; font-size: 10pt">
              <th colspan="4">
                Crédito solicitado + Juros de
                {{ currentLoan.interestRate * 100 }}%
              </th>
              <th
                class="text-right"
                v-money-format="totalAmount(currentLoan)"
              ></th>
            </tr>
          </tbody>
        </table>
        <b-alert
          show
          dismissible
          variant="danger"
          class="text-center"
          v-if="totalGuaranteeAmount < totalAmount(currentLoan)"
        >
          <b-icon icon="exclamation-circle-fill" variant="danger"></b-icon>
          Garantias insuficientes!
        </b-alert>
        <b-row>
          <b-col></b-col>
          <b-col cols="3"
            ><b-button
              type="submit"
              size="sm"
              variant="secondary"
              @click="openGuaranteesSlide()"
              class="mt-2 mb-2"
              block
              >Fotos de garantia
              <b-icon icon="image" font-scale="1"></b-icon></b-button
          ></b-col>
          <b-col cols="3">
            <b-button
              v-if="checkElegibility(currentLoan)"
              type="submit"
              size="sm"
              variant="success"
              :disabled="user.userRole != 1 || currentLoan.status > 0"
              @click="approveLoan()"
              class="mt-2 mb-2"
              block
              >Aprovar Crédito <b-icon icon="save2" font-scale="1"></b-icon
            ></b-button>
            <b-button
              v-else
              type="submit"
              size="sm"
              variant="danger"
              :disabled="user.userRole != 1"
              @click="rejectLoan(currentLoan)"
              class="mt-2 mb-2"
              block
              >Rejeitar Crédito <b-icon icon="x-lg" font-scale="1"></b-icon
            ></b-button>
          </b-col>
        </b-row>
      </b-overlay>
    </b-modal>

    <b-modal hide-footer ref="delete-loan" title="Deletar">
      <p class="text-danger text-center">
        Deseja realmente excluir este financiamento?
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block size="sm" variant="danger" @click="decidedToDelete()"
            >Excluir</b-button
          >
        </b-col>
      </b-row>
    </b-modal>

    <b-modal hide-footer ref="delete-guarantee" title="Deletar">
      <p class="text-danger text-center">
        {{
          currentLoan.status > 0
            ? "Não tem permissão de excluir esta garantia"
            : "Deseja realmente excluir esta garantia?"
        }}
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletionGuarantee()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button
            :disabled="currentLoan.status > 0"
            block
            size="sm"
            variant="danger"
            @click="decidedToDeleteGuarantee()"
            >Excluir</b-button
          >
        </b-col>
      </b-row>
    </b-modal>

    <b-modal
      hide-footer
      ref="show-guarantees"
      class="text-center"
      title="Bens de garantia"
    >
      <b-carousel
        id="carousel-fade"
        style="text-shadow: 0px 0px 2px #000"
        fade
        indicators
        img-width="512"
        img-height="240"
      >
        <b-carousel-slide
          v-for="photo in loanGuarantees"
          :key="photo.id"
          :caption="convertMoney(photo.purchaseAmount)"
          :img-src="photo.guaranteeFileUrl"
        ></b-carousel-slide>
      </b-carousel>
    </b-modal>

    <b-modal
      hide-footer
      ref="loan-payment"
      title="Plano De Amortização"
      size="xl"
    >
      <AmortizationPlan :current-loan="currentLoan" />
    </b-modal>
  </div>
</template>
<script>
import { mapGetters } from "vuex";
import MoneyFormat from "@/utils/moneyFormat";
import firebase from "firebase";
import logs from "@/utils/logs";
import AmortizationPlan from "./AmortizationPlan.vue";
import axios from "axios";
import moment from "moment";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  name: "item-loan",

  components: {
    AmortizationPlan,
  },

  data: () => ({
    form: {
      guaranteeDescription: "",
      guaranteeFileUrl: "",
      purchaseAmount: 0,
      status: 0,
    },

    selectedFile: "",
    uploadValue: 0,

    customerLoanAmortization: [],
    loanGuarantees: [],
    today: moment(),
    currentLoan: 0,
    guaranteeId: 0,
    totalGuaranteeAmount: 0,
  }),

  created() {},

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "currentCustomer",
      "customerLoans",
      "customerTranzactions",
      "company",
    ]),
  },

  methods: {
    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    totalAmount(loan) {
      return loan.amount * loan.interestRate + loan.amount;
    },

    checkElegibility(loan) {
      const elegibility = loan.amount * loan.interestRate + loan.amount;
      return this.totalGuaranteeAmount >= elegibility ? true : false;
    },

    openGuaranteesSlide() {
      this.$refs["show-guarantees"].show();
    },

    deleteLoan(loan) {
      this.loanId = loan.id;
      this.$refs["delete-loan"].show();
    },

    deleteGuarantee(id) {
      this.guaranteeId = id;
      this.$refs["delete-guarantee"].show();
    },

    getLoanStatus(status) {
      if (status == 0) {
        return "Em processamento";
      } else if (status == -1) {
        return "Rejeitado";
      } else if (status == 1) {
        return "Financiado";
      } else if (status == 2) {
        return "Saneado";
      } else if (status == 3) {
        return "Terminado";
      }
    },

    cancelDeletion() {
      this.$refs["delete-loan"].hide();
    },

    cancelDeletionGuarantee() {
      this.$refs["delete-guarantee"].hide();
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/loan/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            this.getCustomerLoans();
            this.$refs["delete-loan"].hide();
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.$refs["delete-loan"].hide();
          }
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-loan"].hide();
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    decidedToDeleteGuarantee() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/deleteGuarantee/${this.guaranteeId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            this.getLoanGuarantees();
            this.$refs["delete-guarantee"].hide();
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.$refs["delete-guarantee"].hide();
          }
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-guarantee"].hide();
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["delete-guarantee"].hide();
        });
    },

    getCustomerLoans() {
      this.$store.dispatch(
        "getCustomerLoans",
        this.currentCustomer.accountNumber
      );
    },

    previewLoan(loan) {
      this.currentLoan = loan;
      this.getLoanGuarantees();
      this.$refs["preview-loan"].show();
    },

    onFileChange(e) {
      this.selectedFile = e.target.files[0];
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    async printContract() {
      const docDefinition = {
        pageOrientation: "portrait",
        content: [
          {
            text: "PDF Generated with Image from external URL",
            fontSize: 20,
          },
          {
            image: await this.getBase64ImageFromURL(this.company.companyLogo),
          },
        ],
      };
      pdfMake.createPdf(docDefinition).open();
    },

    getBase64ImageFromURL(url) {
      return new Promise((resolve, reject) => {
        var img = new Image();
        img.setAttribute("crossOrigin", "anonymous");
        img.onload = () => {
          var canvas = document.createElement("canvas");
          canvas.width = img.width;
          canvas.height = img.height;
          var ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0);
          var dataURL = canvas.toDataURL("image/png");
          resolve(dataURL);
        };
        img.onerror = (error) => {
          reject(error);
        };
        img.src = url;
      });
    },

    onUploadFile() {
      if (!this.selectedFile) {
        this.showToast(
          "Erro!",
          "warning",
          "Seleccione um documento por favor!"
        );
        return;
      }

      if (!this.form.guaranteeDescription) {
        this.showToast(
          "Erro!",
          "warning",
          "Digite a descrição da garantia por favor!"
        );
        return;
      }
      this.$store.commit("LOADING_STATUS", true);
      const storageRef = firebase
        .storage()
        .ref(
          `/customer/${this.currentCustomer.accountNumber}/${this.selectedFile.name}`
        )
        .put(this.selectedFile);
      storageRef.on(
        `state_changed`,
        (snapshot) => {
          this.uploadValue =
            (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        },
        (err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        },
        () => {
          this.uploadValue = 0;
          storageRef.snapshot.ref.getDownloadURL().then((url) => {
            this.form.guaranteeFileUrl = url;
            this.uploadGuaranteeFile();
          });
        }
      );
    },

    uploadGuaranteeFile() {
      this.$store.commit("LOADING_STATUS", true);
      this.form.loanId = this.currentLoan.id;
      axios
        .post(`/api/createGuarantee`, this.form)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${this.form.guaranteeDescription} avaliado a ${this.convertMoney(
                this.form.purchaseAmount
              )} carregado com sucesso.`,
              "Cadastro de Garantias"
            );
            this.$store.dispatch("addLog", logsParams);
            this.form.guaranteeDescription = "";
            this.form.guaranteeFileUrl = "";
            this.form.selectedFile = "";
            this.form.purchaseAmount = 0;
            this.getLoanGuarantees();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    getLoanGuarantees() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/getLoanGuarantees/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.loanGuarantees = data.result;

            this.totalGuaranteeAmount = this.loanGuarantees.reduce(
              (sum, p) => sum + p.purchaseAmount,
              0
            );
          } else {
            this.loanGuarantees = [];
            this.totalGuaranteeAmount = 0;
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    approveLoan() {
      this.$store.commit("LOADING_STATUS", true);
      const passingValues = {
        companyId: this.company.id,
        accountNumber: this.currentLoan.accountNumber,
        loanId: this.currentLoan.id,
        interestRate: this.currentLoan.interestRate,
        numberOfInstallments: this.currentLoan.numberOfInstallments,
        amount: this.currentLoan.amount,
        status: 0,
      };
      axios
        .post(`/api/createInstallmentsLoan`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `Mutuário ${
                this.currentLoan.accountNumber
              } recebeu ${this.convertMoney(this.currentLoan.amount)}`,
              `Desembolso de crédito para conta ${this.currentLoan.accountNumber}`
            );
            this.$store.dispatch("addLog", logsParams);
            this.getCustomerLoans();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    rejectLoan(loan) {
      this.$store.commit("LOADING_STATUS", true);
      const passingValues = {
        status: -1,
      };
      axios
        .put(`/api/loan/${loan.id}`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${
                this.currentLoan.accountNumber
              }. Crédito rejeitado no valor de ${this.convertMoney(
                this.currentLoan.amount
              )} por insuficiência de garantias`,
              `Financiamento rejeitado`
            );
            this.$store.dispatch("addLog", logsParams);
            this.getCustomerLoans();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    getLoanAmortization(loan) {
      this.currentLoan = loan;
      this.$refs["loan-payment"].show();
    },

    closeLoanPayment(loan) {
      this.currentLoan = loan;
      this.$refs["loan-payment"].hide();
    },
  },
};
</script>
